export const INTERNAL_DO_CLASSES = [
  "WorkspaceDO",
  "BrowserVaultDO",
  "EvalDO",
  "WebhookStoreDO",
] as const;
export type InternalDOClassName = (typeof INTERNAL_DO_CLASSES)[number];
export function productBuiltinByIdentity(source: string, className: string) {
  return (
    PRODUCT_BUILTIN_CATALOG.find(
      (entry) => entry.source === source && entry.className === className
    ) ?? null
  );
}
export function findProductBuiltinService(query: string) {
  for (const entry of PRODUCT_BUILTIN_CATALOG) {
    if (
      entry.kind === "service" &&
      (entry.name === query || (entry.protocols as readonly string[]).includes(query))
    )
      return entry;
  }
  return null;
}
export function productBuiltinMethodCapability(
  source: string,
  className: string,
  method: string
): string | null {
  const policy = productBuiltinMethodPolicy(source, className, method);
  return policy?.capability ?? null;
}
export function productBuiltinMethodPolicy(source: string, className: string, method: string) {
  const entry = productBuiltinByIdentity(source, className);
  if (!entry) return null;
  const methods = ("directMethods" in entry ? entry.directMethods : undefined) as unknown as
    | Record<
        string,
        {
          website: import("@vibestudio/rpc").WebsiteMethodPolicy;
          capability: string;
          tier: "open" | "gated" | "critical";
          session: "family" | "codeOnly";
          sensitivity: "read" | "write" | "admin" | "destructive";
          principals: readonly ("host" | "user" | "code" | "session" | "mission")[];
          presentation: CapabilityPresentation | null;
          execution?: { harness: "attested-system-test" };
          prepared?: {
            resolver: string;
            contextBoundary?: {
              operation:
                | "openPanel"
                | "replacePanel"
                | "reload"
                | "unload"
                | "close"
                | "movePanel"
                | "takeOver"
                | "rebuildPanel"
                | "updatePanelState";
              targetArgument: number;
              targetPath?: readonly (string | number)[];
              requestedContextPath?: readonly (string | number)[];
              requestedContextLookup?: {
                method: string;
                arguments: readonly { argument: number; path?: readonly (string | number)[] }[];
                resultPath: readonly (string | number)[];
              };
            };
            leaves: readonly {
              capability?: string;
              capabilityPrefix?: string;
              requirement:
                | import("./authorization.js").AuthorityRequirement
                | {
                    kind: "selected";
                    principals: readonly ("host" | "user" | "code" | "session" | "mission")[];
                  };
              tier?:
                | "open"
                | "gated"
                | "critical"
                | { selectedFrom: readonly ("gated" | "critical")[] };
            }[];
          };
          effect: { kind: string };
        }
      >
    | undefined;
  if (!methods) return null;
  return Object.prototype.hasOwnProperty.call(methods, method) ? methods[method]! : null;
}
export function productBuiltinCapabilityPresentation(
  capability: string
): CapabilityPresentation | null {
  for (const entry of PRODUCT_BUILTIN_CATALOG) {
    for (const method of Object.values(entry.directMethods)) {
      if (method.capability === capability && method.presentation) return method.presentation;
    }
  }
  return null;
}
export function productBuiltinCapabilityCategory(
  capability: string
): NonNullable<CapabilityPresentation["authorityCategory"]> | null {
  return productBuiltinCapabilityPresentation(capability)?.authorityCategory ?? null;
}
export function productBuiltinMethodRequests(source: string, className: string, method: string) {
  const entry = productBuiltinByIdentity(source, className);
  if (!entry) return [];
  return entry.hostCapabilityRequests
    .filter((request) => (request.methods as readonly string[]).includes(method))
    .map(({ methods: _methods, tier: _tier, evidence: _evidence, ...scope }) => scope);
}
